class Solution {
public:
    int compress(vector<char>& chars) {
        int n = chars.size();
        int write = 0;
        int i = 0;
        while (i < n) {
            char c = chars[i];
            int count = 0;
            while (i < n && chars[i] == c) {
                i++;
                count++;
            }
            chars[write++] = c;
            if (count > 1) {
                int start = write;
                while (count > 0) {
                    chars[write++] = '0' + (count % 10);
                    count /= 10;
                }
                int end = write - 1;
                while (start < end) {
                    char temp = chars[start];
                    chars[start] = chars[end];
                    chars[end] = temp;
                    start++;
                    end--;
                }
            }
        }
        return write;
    }
};
